import { FontAwesomeIcon } from '@fortawesome/react-fontawesome'
import { faGithub, faInstagram } from '@fortawesome/free-brands-svg-icons'

function CareerCard ({year, title, subtitle, description, linkRepo}) {

    const content = (
        <>
            <h3 className='text-sm lg:text-xl'>{title} <span className='ml-2'>{year}</span>{linkRepo && <span className='ml-2'><FontAwesomeIcon icon={linkRepo.includes('instagram.com') ? faInstagram : faGithub}/></span>}</h3>
            <h4 className='text-sm lg:text-xl'>{subtitle}</h4>
            {description && <p className='text-sm lg:text-xl'>{description}</p>}
        </>
    );

    if (linkRepo) {
        return (
            <a href={linkRepo} target="_blank" rel="noreferrer" className="career-card-activable flex flex-col w-full pl-5 text-xl my-5">
                {content}
            </a>
        );
    }

    return (
        <div className="career-card flex flex-col w-full pl-5 text-xl my-5">
            {content}
        </div>
    );
}

export default CareerCard;
