import { createContext, useContext, useEffect, useState } from 'react';

import en from './en';
import es from './es';

export const translations = { en, es };
const STORAGE_KEY = 'lang';
const LOCALES = { en: 'en_US', es: 'es_CL' };

const LanguageContext = createContext(null);

// Priority: ?lang= in URL > saved choice > browser language > English
function getInitialLanguage() {
    const fromUrl = new URLSearchParams(window.location.search).get('lang');
    if (translations[fromUrl]) return fromUrl;

    try {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (translations[saved]) return saved;
    } catch (e) {}

    return navigator.language?.toLowerCase().startsWith('es') ? 'es' : 'en';
}

function setMeta(selector, content) {
    const element = document.querySelector(selector);
    if (element) element.setAttribute('content', content);
}

export function LanguageProvider({ children }) {

    const [language, setLanguage] = useState(getInitialLanguage);
    const t = translations[language];

    // keep <html lang>, title, meta tags and URL in sync with the language
    useEffect(() => {
        document.documentElement.lang = language;
        document.title = t.seo.title;
        setMeta('meta[name="description"]', t.seo.description);
        setMeta('meta[property="og:title"]', t.seo.title);
        setMeta('meta[property="og:description"]', t.seo.description);
        setMeta('meta[property="og:locale"]', LOCALES[language]);
        setMeta('meta[name="twitter:title"]', t.seo.title);
        setMeta('meta[name="twitter:description"]', t.seo.description);

        const url = new URL(window.location.href);
        if (language === 'en') {
            url.searchParams.delete('lang');
        } else {
            url.searchParams.set('lang', language);
        }
        window.history.replaceState(null, '', url);

        try {
            localStorage.setItem(STORAGE_KEY, language);
        } catch (e) {}
    }, [language, t]);

    const toggleLanguage = () => setLanguage(language === 'en' ? 'es' : 'en');

    return (
        <LanguageContext.Provider value={{ language, t, toggleLanguage }}>
            {children}
        </LanguageContext.Provider>
    );
}

export function useLanguage() {
    return useContext(LanguageContext);
}
