import Typed from "typed.js";
import { useEffect, useRef } from "react";

import Button from './Button'
import { useLanguage } from "../i18n/LanguageContext";

function Hero() {

    const element = useRef(null);
    const { t } = useLanguage();

    const handleButtonClick = () => {
        window.open("https://www.linkedin.com/in/uwo-o", "_blank");
    }

    // restart the typing animation when the language changes
    useEffect(() => {
        const typed = new Typed(element.current, {
            strings: t.hero.roles,
            typeSpeed: 30,
            backSpeed: 30,
            backDelay: 1000,
            loop: true
        });

        return () => {
            typed.destroy();
        }
    }, [t]);

    return (
        <header className="hero w-4/5 2xl:w-2/5 pl-8">
            <div className="">
                <p>{t.hero.greeting}</p>
                <h1>Hugo Campos</h1>
                <p>{t.hero.intro} <span ref={element}></span></p>
            </div>
            <div className="flex justify-end">
                <Button onClick={handleButtonClick}>{t.hero.hire}</Button>
            </div>
        </header>
    );
}

export default Hero;
