import Button from './Button';
import { useLanguage } from '../i18n/LanguageContext';

function About() {

    const { t } = useLanguage();

    const years_of_experience = "4"
    const completed_projects = "04"
    const companies_worked = "01"

    const onButtonClick = () => {
        const pdfUrl = "CV-Hugo-Campos.pdf";
        const link = document.createElement("a");
        link.href = pdfUrl;
        link.download = "CV-Hugo-Campos.pdf"; // specify the filename
        document.body.appendChild(link);
        link.click();
    };

    return(
        <section id="about" className="container mx-auto flex items-center flex-col xl:flex-row">
            <div className='1/2 lg:1/3 2xl:w-1/2'>
                <img src="./me.jpg" alt={t.about.imageAlt} loading="lazy" decoding="async" className="me-image items-end hidden xl:block scale-90 xl:scale-90"></img>
            </div>
            <div className="2xl:w-1/2 m-3 xl:m-5 2xl:ml-0 inline-flex flex-col xl:flex-row items-center">
                <div className="w-3/4 2xl:2/3">
                    <h2 className="text-5xl my-5">{t.about.title}</h2>
                    {t.about.paragraphs.map((paragraph, i) => (
                        <p key={i} className="text-lg 2xl:text-xl text-justify mb-7">{paragraph}</p>
                    ))}
                    <div className="my-5 text-xl">
                        <Button onClick={onButtonClick}>{t.about.downloadCV}</Button>
                    </div>
                </div>
                <div className="flex flex-row xl:flex-col lg:4/5 xl:w-1/4 2xl:w-1/3 pl-5">
                    <div className="abt-tag flex justify-between flex-col pl-5 my-5 mr-2 lg:mx-5 2xl:my-12:mx-0">
                        <p className='text-ml ml:text-lg lg:text-xl 2xl:text-2xl'>{t.about.stats.experience}</p>
                        <p className='text-xl ml:text-3xl lg:text-5xl 2xl:text-7xl'>{years_of_experience}</p>
                    </div>
                    <div className="abt-tag flex justify-between flex-col pl-5 my-5 mx-2 lg:mx-5 2xl:my-12:mx-0">
                        <p className='text-ml ml:text-lg lg:text-xl 2xl:text-2xl'>{t.about.stats.projects}</p>
                        <p className='text-xl ml:text-3xl lg:text-5xl 2xl:text-7xl'>{completed_projects}</p>
                    </div>
                    <div className="abt-tag flex justify-between flex-col pl-5 my-5 mx-2 lg:mx-5 2xl:my-12:mx-0">
                        <p className='text-ml ml:text-lg lg:text-xl 2xl:text-2xl'>{t.about.stats.companies}</p>
                        <p className='text-xl ml:text-3xl lg:text-5xl 2xl:text-7xl'>{companies_worked}</p>
                    </div>
                </div>
            </div>
        </section>
    );
}

export default About;