import ButtonCareer from './ButtonCareer';
import CareerCard from './CareerCard';
import { useLanguage } from '../i18n/LanguageContext';

import {useState} from 'react';

const TABS = ['projects', 'experience', 'education'];

function Career () {

    const [activeTab, setActiveTab] = useState('experience');
    const { t } = useLanguage();

    return(
        <section id="career" className="w-4/5 lg:w-1/2 container mx-auto flex items-center flex-col my-20 h-screen">
            <p className="career-h2 text-xl 2xl:text-3xl">{t.career.kicker}</p>
            <h2 className="career-h1 text-2xl lg:text-4xl 2xl:text-6xl">{t.career.title}</h2>
            <hr className='w-full mt-10'/>
            <div className="flex flex-row mt-10">
                {TABS.map(tab => (
                    <ButtonCareer key={tab} id={`btn-${tab}`} onClick={() => setActiveTab(tab)} className={`button-career text-md mx-2 px-3 lg:text-2xl lg:mx-5 lg:px-5 py-2 ${activeTab === tab ? 'active' : ''}`}>{t.career.tabs[tab]}</ButtonCareer>
                ))}
            </div>

            <div key={activeTab} id={activeTab} className='flex flex-col mt-10 animate-fade-right'>
                {t.career[activeTab].map(item => (
                    <CareerCard key={item.title + item.year} year={item.year} title={item.title} subtitle={item.subtitle} description={item.description} linkRepo={item.link}/>
                ))}
            </div>
        </section>
    );
}

export default Career;
