import { useState, useEffect } from "react";

import { useLanguage } from "../i18n/LanguageContext";

function Navbar() {

    const [isHide, setIsHide] = useState(false);
    const { t, toggleLanguage } = useLanguage();

    // change base ond scrollY
    useEffect(() => {

        const handeActive = (e) => {
            if (window.innerWidth > 768) {
                if (window.scrollY > 20) {
                    if (e.clientY < 100) {
                        setIsHide(false);
                    } else {
                        setIsHide(true);
                    }
                }
                else {
                    setIsHide(false);
                }
            }
        }

        if (isHide) {
            document.querySelector("nav").classList.add("hide");
        } else {
            document.querySelector("nav").classList.remove("hide");
        }

        window.addEventListener("scroll", handeActive);
        window.addEventListener("mousemove", handeActive);

        return () => {
            window.removeEventListener("scroll", handeActive);
            window.removeEventListener("mousemove", handeActive);
        }
    });

    return (
        <nav className="z-20">
            <ul className="nav-links inline-flex flex-row items-center">
                <li className="p-3 xl:px-5 p-name">uwo.</li>
                <li className="flex items-center" ><a className="flex items-center p-3 px-10" href="#home">{t.nav.home}</a></li>
                <li className="flex items-center" ><a className="flex items-center p-3 px-10" href="#about">{t.nav.about}</a></li>
                <li className="flex items-center" ><a className="flex items-center p-3 px-10" href="#career">{t.nav.career}</a></li>
            </ul>
            <ul className="nav-lang inline-flex flex-row items-center">
                <li className="flex items-center">
                    <button className="flex items-center p-3 px-10" onClick={toggleLanguage} aria-label={t.nav.languageLabel}>
                        <span className="hidden md:inline">{t.nav.language}</span>
                        <span className="md:hidden">{t.nav.languageShort}</span>
                    </button>
                </li>
            </ul>
        </nav>
    )
}

export default Navbar;